def _cloud_sync():
    while True:
        try:
            with urllib.request.urlopen(CLOUD_STATE_URL, timeout=8) as r:
                d = json.loads(r.read().decode()).get('telemetry', {})
                if d.get('pairs'):
                    with open(STATE_FILE, 'w') as f:
                        json.dump(d, f)
        except Exception:
            pass
        time.sleep(10)

threading.Thread(target=_cloud_sync, daemon=True).start()

