_orig_lbl = tk.Label.configure
def _lbl_cfg(self, cnf=None, **kw):
    if '[3.8-flash]' in str(kw.get('text', '')).lower():
        kw['fg'] = '#fbbf24'
    return _orig_lbl(self, cnf, **kw)
